def compute_acf(frame, max_lag):
    n = len(frame)
    acf = np.zeros(max_lag)
    energy = np.sum(frame**2)
    if energy == 0:
        return acf
    for k in range(max_lag):
        acf[k] = np.sum(frame[:n-k] * frame[k:]) / energy
    return acf

def frame_zcr(signal, frame_length, hop_size):
    num_frames = 1 + (len(signal) - frame_length) // hop_size
    zcrs = []
    for i in range(num_frames):
        frame = signal[i * hop_size : i * hop_size + frame_length]
        zcr = np.sum(np.abs(np.diff(np.sign(frame)))) / (2 * (len(frame) - 1))
        zcrs.append(zcr)
    return np.array(zcrs)

def amdf(frame):
    N = len(frame)
    return [sum(abs(frame[n] - frame[n+k]) for n in range(N-k)) for k in range(N)]

import numpy as np
def frame_mse(clean, degraded, frame_size=160):
    errors = []
    for i in range(0, len(clean) - frame_size, frame_size):
        c = clean[i:i+frame_size]
        d = degraded[i:i+frame_size]
        errors.append(np.mean((c - d)**2))
    return np.mean(errors)

