import numpy as np
def hps(spec, num_harmonics=4):
    downsampled = [spec[::i] for i in range(1, num_harmonics + 1)]
    min_len = min(len(d) for d in downsampled)
    prod = np.prod([d[:min_len] for d in downsampled], axis=0)
    return np.argmax(prod)

import numpy as np
def is_valid_transition(matrix):
    return np.allclose(matrix.sum(axis=1), 1.0)

def autocorr(signal, p):
    R = [np.sum(signal[k:] * signal[:len(signal)-k]) for k in range(p+1)]
    return np.array(R)

def find_formant_frequencies(a_coeffs, fs):
    roots = np.roots(np.concatenate(([1.0], -a_coeffs)))
    # Filter roots with positive imaginary part
    angles = np.angle(roots[np.imag(roots) > 0])
    formants = angles * (fs / (2 * np.pi))
    return np.sort(formants)

def calculate_lpc_gain(E_p, R0, a_coeffs):
    # G^2 = E_p = R[0] - sum(a_k * R[k])
    # Here E_p is final prediction error from Levinson-Durbin
    return np.sqrt(E_p)

def calculate_wer(reference, hypothesis):
    r = reference.split()
    h = hypothesis.split()
    d = [[i + j for j in range(len(h) + 1)] for i in range(len(r) + 1)]
    for i in range(1, len(r) + 1):
        for j in range(1, len(h) + 1):
            if r[i-1] == h[j-1]:
                d[i][j] = d[i-1][j-1]
            else:
                d[i][j] = min(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + 1)
    return d[len(r)][len(h)] / len(r)
